  unweighted_log_RR_95CI <- quantile(unweighted_log_RR, probs = c(0.025, 0.975))
  unweighted_log_RR_p <- 1 - sum(unweighted_log_RR >= 0)/n_post_draws
  unweighted_log_RR_sd <- sd(unweighted_log_RR)
  
