  unweighted_RR_sd <- sd(exp(unweighted_log_RR))
  
  #unweighted RR greater than or equal to
  unweighted_log_RR_ge <- rowMeans(log_RR_ge[, 2:(c)])
  unweighted_log_RR_ge_95CI <- quantile(unweighted_log_RR_ge, probs = c(0.025, 0.975))
