              weighted_RD_cum_sd = weighted_RD_cumsd,
              weighted_RD_both_CI = weighted_RD_both95CI,
              weighted_RD_both_p = weighted_RD_bothp,
              weighted_RD_both_sd = weighted_RD_bothsd, 
              # weighted_RD_Bsd_overall = weighted_RD_Bsd_overall,
