    weights_split[s,] <- ((p_y_ctl_est_average[j] + p_y_ctl_est_average[k]) * (abs(utility[j] - utility[k]))) / sum((p_y_ctl_est_average[j] + p_y_ctl_est_average[k]) * (abs(utility[j] - utility[k])))
    weights_cum[s,] <- (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]) * (abs(utility[j] - utility[k]))) / sum((p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * (abs(utility[j] - utility[k])))
    weights_both[s,] <- (p_y_ctl_est_average[j] + p_y_ctl_est_average[k]) * (abs(utility[j] - utility[k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) / 
