# adjusted sensitivity analysis 
sensitivity_utility_dichotomize <- function(stanfit, dat, structured_dat, base_utility,
                                       outcome, trt, covs, util_modify, seed = 12345) { 
  set.seed(seed)
  modfit <- as.data.frame(stanfit)
  
  alphas <- modfit[,grep('alpha\\[', colnames(modfit))]
  alpha <- colMeans(alphas)
  
  betas <- modfit[,grep('beta\\[', colnames(modfit))]
  beta <- colMeans(betas)
  beta <- matrix(beta, nrow=1) %*% t(structured_dat$wqrX$Rinv[2:4, 2:4])
  
  c <- length(alpha)/2 +1
  
  predicted_trt_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_ctl_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_trt_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_ctl_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  p_y_ctl <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_trt <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_ctl_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_trt_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  
  
  
  num_covs <- length(covs)
  covariate_mat <- as.data.frame(matrix(data = NA, nrow = nrow(dat), ncol = num_covs - 1))
  
  # assume the first covariate is the treatment arm 
  for(i in 1:num_covs) {
    if (is.numeric(dat[[covs[i]]]) == T) {
      covariate_mat[,i] <- beta[i] * dat[[covs[i]]]
    } else {
      # only works for numeric and binary with "Yes" as the value
      covariate_mat[,i] <- beta[i] * (dat[[covs[i]]] == "Yes")
    }
  }
  
  for (i in 2:c) {
    predicted_trt_geq[,i-1] <- plogis(alpha[2*i - 2] + rowSums(covariate_mat))
    predicted_ctl_geq[,i-1] <- plogis(alpha[2*i - 3] + rowSums(covariate_mat))
  }
  
  
  predicted_trt_leq <-  1 - predicted_trt_geq
  predicted_ctl_leq <-  1 - predicted_ctl_geq
  
  # calculate p(Y = i | control) for i = 1, ... , c
  for (i in 1:c) {
    if (i == 1) {
      p_y_ctl_est[,1] <-  predicted_ctl_leq[,1]
      p_y_trt_est[,1] <-  predicted_trt_leq[,1]
    } else if (i == 2) {
      p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - p_y_ctl_est[,1]
      p_y_trt_est[,i] <-  predicted_trt_leq[,i] - p_y_trt_est[,1]
    } else if (i == c) {
      p_y_ctl_est[,c] <- 1 - rowSums(p_y_ctl_est[,1:(c-1)])
      p_y_trt_est[,c] <- 1 - rowSums(p_y_trt_est[,1:(c-1)])
    } else {
      p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - rowSums(p_y_ctl_est[,1:(i-1)])
      p_y_trt_est[,i] <-  predicted_trt_leq[,i] - rowSums(p_y_trt_est[,1:(i-1)])
    }
  }
  
  # correct for any negative probabilities 
  if (any(p_y_ctl_est < 0)) {
    p_y_ctl_est[which(p_y_ctl_est < 0)] <- 0 
    p_y_ctl_est <- p_y_ctl_est/rowSums(p_y_ctl_est)
  }
  
  if (any(p_y_trt_est < 0)) {
    p_y_trt_est[which(p_y_trt_est < 0)] <- 0 
    p_y_trt_est <- p_y_trt_est/rowSums(p_y_trt_est)
  }
  
  
  p_y_est <- (p_y_ctl_est + p_y_trt_est)/2
  
  # get weights from the data 
  p_y_ctl <- unname(table(dat[[trt]], dat[[outcome]])[1,])/sum(dat[[trt]] == -0.5)
  p_y_trt <- unname(table(dat[[trt]], dat[[outcome]])[2,])/sum(dat[[trt]] == 0.5)
  p_y <- unname(table(dat[[outcome]]))/nrow(dat)
  
  # use Bayesian bootstrap to marginalize the probabilities
  weights <- t(rdirichlet(1, rep(1, nrow(dat))))
  p_y_ctl_est_bb <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
  p_y_trt_est_bb <- apply(p_y_trt_est, 2, weighted.mean, w = weights)
  p_y_est_bb <- (p_y_ctl_est_bb + p_y_trt_est_bb) /2
  
  p_y_ctl_leq_average <- apply(predicted_ctl_leq, 2, weighted.mean, w = weights)
  p_y_trt_leq_average <- apply(predicted_trt_leq, 2, weighted.mean, w = weights)
  p_y_ctl_geq_average <- apply(predicted_ctl_geq, 2, weighted.mean, w = weights)
  p_y_trt_geq_average <- apply(predicted_trt_geq, 2, weighted.mean, w = weights)
  
  
  RD_leq <- p_y_trt_leq_average - p_y_ctl_leq_average
  RD_geq <- p_y_ctl_geq_average - p_y_trt_geq_average
  
  
  OR <- (p_y_trt_leq_average / (1- p_y_trt_leq_average)) / (p_y_ctl_leq_average / (1- p_y_ctl_leq_average))
  
  RR_leq <- p_y_trt_leq_average / p_y_ctl_leq_average
  RR_geq <- p_y_ctl_geq_average / p_y_trt_geq_average
  
  # set up how to modify utility value
  # base_utility defines the base utility values that we will modify
  # util_modify defines which utility value we want to modify 
  # need to determine the correct ratios for the other values 
  ratio <- NA 
  for (i in 2:(c-1)) {
    if (i < util_modify) {
      ratio[i] <- (base_utility[i] -  base_utility[util_modify])/ (100 -  base_utility[util_modify])
    } else if (i > util_modify) {
      ratio[i] <- (base_utility[i])/(base_utility[util_modify])
    }
  }
  # num_util_above <- c - max(util_modify)
  # num_util_below <- min(util_modify) - 1
  # even_util_no_jump <- rev(seq(0, 100, by = 100/(c-2)))
  # even_util_value <- even_util_no_jump[min(util_modify) ]
  utility_value <- NA
  utility_matrix <- matrix(data = NA, nrow = 101, ncol = c)
  utility_matrix[,1] <- 100
  utility_matrix[,c] <- 0
  utility_matrix[,util_modify] <- 0:100
  # pull NA columns 
  for (i in 1:nrow(utility_matrix)) {
    # utility_value[i] <- utility_matrix[i, util_modify]
    # make catch for if the utility being modified is 2 or c-1
    if (util_modify == 2) {
      utility_matrix[i,(util_modify+1):(c-1)] <- utility_matrix[i,util_modify]*ratio[(util_modify+1):(c-1)]
    } else if (util_modify == c-1) {
      utility_matrix[i,2:(util_modify-1)] <- (100 - utility_matrix[i,util_modify])*ratio[2:(util_modify-1)] + utility_matrix[i,util_modify]
    } else {
      utility_matrix[i,2:(util_modify-1)] <- (100 - utility_matrix[i,util_modify])*ratio[2:(util_modify-1)] + utility_matrix[i,util_modify]
      utility_matrix[i,(util_modify+1):(c-1)] <- utility_matrix[i,util_modify]*ratio[(util_modify+1):(c-1)]
    }
  }
  
  
  j <- 1:(c-1)
  k <- 2:c
  
  weighted_RD_both <- NA
  weighted_RD_util <- NA
  log_weighted_OR_both <- NA
  log_weighted_OR_util <- NA
  log_weighted_RR_both <- NA
  log_weighted_RR_util <- NA
  # utility_value <- NA
  for (i in 1:nrow(utility_matrix)) {
    utility_value[i] <- utility_matrix[i, util_modify]
    
    # fully bayesian approach 
    # control weighted  
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    weighted_RD_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    weighted_RD_util[i] <- numerator/denominator
  
    
    # bayesian approach
    #calculate weighted OR with control probability as weights
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * log(OR[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    log_weighted_OR_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(OR[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    log_weighted_OR_util[i] <- numerator/denominator
    
    # bayesian approach
    #calculate weighted RR with control probability as weights
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * log(RR_leq[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    log_weighted_RR_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(RR_leq[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    log_weighted_RR_util[i] <- numerator/denominator
  }
  
  return(list(utility_value = utility_value,
              weighted_RD_both = weighted_RD_both, 
              weighted_RD_util = weighted_RD_util, 
              log_weighted_OR_both = log_weighted_OR_both,
              log_weighted_OR_util = log_weighted_OR_util,
              log_weighted_RR_both = log_weighted_RR_both,
              log_weighted_RR_util = log_weighted_RR_util))
  
}

# adjusted sensitivity analysis 
sensitivity_utility_adj_bb <- function(stanfit, dat, structured_dat,
                                       outcome, trt, covs, util_modify, seed = 12345) { 
  set.seed(seed)
  modfit <- as.data.frame(stanfit)
  
  alphas <- modfit[,grep('alpha\\[', colnames(modfit))]
  alpha <- colMeans(alphas)
  
  betas <- modfit[,grep('beta\\[', colnames(modfit))]
  beta <- colMeans(betas)
  beta <- matrix(beta, nrow=1) %*% t(structured_dat$wqrX$Rinv[2:4, 2:4])
  
  c <- length(alpha)/2 +1
  
  predicted_trt_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_ctl_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_trt_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_ctl_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  p_y_ctl <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_trt <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_ctl_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_trt_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  
  
  
  num_covs <- length(covs)
  covariate_mat <- as.data.frame(matrix(data = NA, nrow = nrow(dat), ncol = num_covs - 1))
  
  # assume the first covariate is the treatment arm 
  for(i in 1:num_covs) {
    if (is.numeric(dat[[covs[i]]]) == T) {
      covariate_mat[,i] <- beta[i] * dat[[covs[i]]]
    } else {
      # only works for numeric and binary with "Yes" as the value
      covariate_mat[,i] <- beta[i] * (dat[[covs[i]]] == "Yes")
    }
  }
  
  for (i in 2:c) {
    predicted_trt_geq[,i-1] <- plogis(alpha[2*i - 2] + rowSums(covariate_mat))
    predicted_ctl_geq[,i-1] <- plogis(alpha[2*i - 3] + rowSums(covariate_mat))
  }
  
  
  predicted_trt_leq <-  1 - predicted_trt_geq
  predicted_ctl_leq <-  1 - predicted_ctl_geq
  
  # calculate p(Y = i | control) for i = 1, ... , c
  for (i in 1:c) {
    if (i == 1) {
      p_y_ctl_est[,1] <-  predicted_ctl_leq[,1]
      p_y_trt_est[,1] <-  predicted_trt_leq[,1]
    } else if (i == 2) {
      p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - p_y_ctl_est[,1]
      p_y_trt_est[,i] <-  predicted_trt_leq[,i] - p_y_trt_est[,1]
    } else if (i == c) {
      p_y_ctl_est[,c] <- 1 - rowSums(p_y_ctl_est[,1:(c-1)])
      p_y_trt_est[,c] <- 1 - rowSums(p_y_trt_est[,1:(c-1)])
    } else {
      p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - rowSums(p_y_ctl_est[,1:(i-1)])
      p_y_trt_est[,i] <-  predicted_trt_leq[,i] - rowSums(p_y_trt_est[,1:(i-1)])
    }
  }
  
  # correct for any negative probabilities 
  if (any(p_y_ctl_est < 0)) {
    p_y_ctl_est[which(p_y_ctl_est < 0)] <- 0 
    p_y_ctl_est <- p_y_ctl_est/rowSums(p_y_ctl_est)
  }
  
  if (any(p_y_trt_est < 0)) {
    p_y_trt_est[which(p_y_trt_est < 0)] <- 0 
    p_y_trt_est <- p_y_trt_est/rowSums(p_y_trt_est)
  }
  
  
  p_y_est <- (p_y_ctl_est + p_y_trt_est)/2
  
  # get weights from the data 
  p_y_ctl <- unname(table(dat[[trt]], dat[[outcome]])[1,])/sum(dat[[trt]] == -0.5)
  p_y_trt <- unname(table(dat[[trt]], dat[[outcome]])[2,])/sum(dat[[trt]] == 0.5)
  p_y <- unname(table(dat[[outcome]]))/nrow(dat)
  
  # use Bayesian bootstrap to marginalize the probabilities
  weights <- t(rdirichlet(1, rep(1, nrow(dat))))
  p_y_ctl_est_bb <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
  p_y_trt_est_bb <- apply(p_y_trt_est, 2, weighted.mean, w = weights)
  p_y_est_bb <- (p_y_ctl_est_bb + p_y_trt_est_bb) /2
  
  p_y_ctl_leq_average <- apply(predicted_ctl_leq, 2, weighted.mean, w = weights)
  p_y_trt_leq_average <- apply(predicted_trt_leq, 2, weighted.mean, w = weights)
  p_y_ctl_geq_average <- apply(predicted_ctl_geq, 2, weighted.mean, w = weights)
  p_y_trt_geq_average <- apply(predicted_trt_geq, 2, weighted.mean, w = weights)
  
  
  RD_leq <- p_y_trt_leq_average - p_y_ctl_leq_average
  RD_geq <- p_y_ctl_geq_average - p_y_trt_geq_average
  
  
  OR <- (p_y_trt_leq_average / (1- p_y_trt_leq_average)) / (p_y_ctl_leq_average / (1- p_y_ctl_leq_average))
  
  RR_leq <- p_y_trt_leq_average / p_y_ctl_leq_average
  RR_geq <- p_y_ctl_geq_average / p_y_trt_geq_average
  
  # set up how to modify utility value 
  num_util_above <- c - max(util_modify)
  num_util_below <- min(util_modify) - 1
  even_util_no_jump <- rev(seq(0, 100, by = 100/(c-2)))
  even_util_value <- even_util_no_jump[min(util_modify) ]
  utility_matrix <- matrix(data = NA, nrow = 101, ncol = c)
  utility_matrix[,1] <- 100
  utility_matrix[,c] <- 0
  utility_matrix[,min(util_modify)] <- even_util_value + 0:100 * (1-even_util_value/100)
  utility_matrix[,max(util_modify)] <- even_util_value - 0:100 * (even_util_value/100)
  # pull NA columns 
  for (i in 1:nrow(utility_matrix)) {
    utility_matrix[i,2:(min(util_modify)-1)] <- rev(seq(utility_matrix[i,min(util_modify)], utility_matrix[i,1], 
                                                        length.out = min(util_modify)))[2:(min(util_modify)-1)]
    utility_matrix[i,(max(util_modify)+1):(c-1)] <- rev(seq(utility_matrix[i,c], utility_matrix[i,max(util_modify)], 
                                                            length.out = c+1-max(util_modify)))[2:(c-max(util_modify))]
  }
  
  
  j <- 1:(c-1)
  k <- 2:c
  
  weighted_RD_both <- NA
  weighted_RD_util <- NA
  log_weighted_OR_both <- NA
  log_weighted_OR_util <- NA
  log_weighted_RR_both <- NA
  log_weighted_RR_util <- NA
  # utility_value <- NA
  for (i in 1:nrow(utility_matrix)) {
    # utility_value[i] <- utility_matrix[i, utility]
    
    # fully bayesian approach 
    # control weighted  
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    weighted_RD_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    weighted_RD_util[i] <- numerator/denominator
    
    
    # bayesian approach
    #calculate weighted OR with control probability as weights
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * log(OR[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    log_weighted_OR_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(OR[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    log_weighted_OR_util[i] <- numerator/denominator
    
    # bayesian approach
    #calculate weighted RR with control probability as weights
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * log(RR_leq[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    log_weighted_RR_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(RR_leq[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    log_weighted_RR_util[i] <- numerator/denominator
  }
  
  return(list(weighted_RD_both = weighted_RD_both, 
              weighted_RD_util = weighted_RD_util, 
              log_weighted_OR_both = log_weighted_OR_both,
              log_weighted_OR_util = log_weighted_OR_util,
              log_weighted_RR_both = log_weighted_RR_both,
              log_weighted_RR_util = log_weighted_RR_util))
  
}


# sensitivity analysis of changing utility values, CI calculation
sensitivity_utility_CI_dichotomize <- function(stanfit, structured_dat, n_post_draws = 4000, dat,  
                                          outcome, trt, covs, base_utility, util_modify, seed = 12345) { 
  set.seed(seed)
  # first calculate P(y >= i | ctl) and P(y >= i | trt) for all i
  stanmod <- as.data.frame(stanfit)
  alphas_post <- stanmod[,grep('alpha\\[', colnames(stanmod))]
  c <- ncol(alphas_post)/2 +1
  
  betas <- stanmod[,grep('beta\\[', colnames(stanmod))]
  betas_post <- as.matrix(betas) %*% t(structured_dat$wqrX$Rinv[2:4, 2:4])
  
  
  PPO_ctl_geq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  PPO_trt_geq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  PPO_ctl_leq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  PPO_trt_leq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  
  
  
  wRD_both <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  wRD_util <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  log_wOR_both <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  log_wOR_util <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  log_wRR_both <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  log_wRR_ge_both <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  log_wRR_util <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  log_wRR_ge_util <- matrix(data = NA, ncol = n_post_draws, nrow = 101)
  
  # weights_split <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  # weights_cum <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  # weights_both <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  
  #NB <- matrix(data = NA, nrow = n_post_draws, ncol = 1)
  RD_leq_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  OR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  RR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  RR_save_geq <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  log_OR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  log_RR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  log_RR_ge_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  
  foreach (s = 1:n_post_draws) %do% {
    
    predicted_trt_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    predicted_ctl_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    predicted_trt_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    predicted_ctl_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    
    # if (iprior == 0){
    #   coefs <- posterior_draws[i, ]
    # } else {
    #   coefs <- c(-coef(b)[1:3], coef(b)[4:9])
    # }
    
    alpha <- alphas_post[s, ]
    beta <- betas_post[s, ]
    
    num_covs <- length(covs)
    covariate_mat <- as.data.frame(matrix(data = NA, nrow = nrow(dat), ncol = num_covs - 1))
    
    # assume the first covariate is the treatment arm 
    for(i in 1:num_covs) {
      if (is.numeric(dat[[covs[i]]]) == T) {
        covariate_mat[,i] <- beta[i] * dat[[covs[i]]]
      } else {
        # only works for numeric and binary with "Yes" as the value
        covariate_mat[,i] <- beta[i] * (dat[[covs[i]]] == "Yes")
      }
    }
    
    for (i in 2:c) {
      predicted_trt_geq[,i-1] <- plogis(as.numeric(alpha[2*i - 2]) + rowSums(covariate_mat))
      predicted_ctl_geq[,i-1] <- plogis(as.numeric(alpha[2*i - 3]) + rowSums(covariate_mat))
    }
    
    predicted_trt_leq <-  1 - predicted_trt_geq
    predicted_ctl_leq <-  1 - predicted_ctl_geq
    
    p_y_trt_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
    p_y_ctl_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
    for (i in 1:c) {
      if (i == 1) {
        p_y_ctl_est[,1] <-  predicted_ctl_leq[,1]
        p_y_trt_est[,1] <-  predicted_trt_leq[,1]
      } else if (i == 2){
        p_y_ctl_est[,2] <- predicted_ctl_leq[,i] - predicted_ctl_leq[,1]
        p_y_trt_est[,2] <- predicted_trt_leq[,i] - predicted_trt_leq[,1]
      } else if (i == c) {
        p_y_ctl_est[,c] <- 1 - rowSums(p_y_ctl_est[,1:(c-1)])
        p_y_trt_est[,c] <- 1 - rowSums(p_y_trt_est[,1:(c-1)])
      } else {
        p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - apply(p_y_ctl_est[,1:(i-1)], 1, sum)
        p_y_trt_est[,i] <-  predicted_trt_leq[,i] - apply(p_y_trt_est[,1:(i-1)], 1, sum)
      }
    }
    
    # correct for any negative probabilities 
    if (any(p_y_ctl_est < 0)) {
      p_y_ctl_est[which(p_y_ctl_est < 0)] <- 0 
      p_y_ctl_est <- p_y_ctl_est/rowSums(p_y_ctl_est)
    }
    
    if (any(p_y_trt_est < 0)) {
      p_y_trt_est[which(p_y_trt_est < 0)] <- 0 
      p_y_trt_est <- p_y_trt_est/rowSums(p_y_trt_est)
    }
    
    
    p_y_est <- (p_y_ctl_est + p_y_trt_est)/2
    
    # get weights from the data 
    p_y_ctl <- unname(table(dat[[trt]], dat[[outcome]])[1,])/sum(dat[[trt]] == -0.5)
    p_y_trt <- unname(table(dat[[trt]], dat[[outcome]])[2,])/sum(dat[[trt]] == 0.5)
    p_y <- as.vector(unname(table(dat[[outcome]]))/nrow(dat))
    
    weights <- t(rdirichlet(1, rep(1, nrow(dat))))
    p_y_ctl_est_bb <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
    p_y_trt_est_bb <- apply(p_y_trt_est, 2, weighted.mean, w = weights)
    p_y_est_bb <- (p_y_ctl_est_bb + p_y_trt_est_bb) /2
    
    p_y_ctl_leq_average <- apply(predicted_ctl_leq, 2, weighted.mean, w = weights)
    p_y_trt_leq_average <- apply(predicted_trt_leq, 2, weighted.mean, w = weights)
    p_y_ctl_geq_average <- apply(predicted_ctl_geq, 2, weighted.mean, w = weights)
    p_y_trt_geq_average <- apply(predicted_trt_geq, 2, weighted.mean, w = weights)
    
    p_y_est_average <- apply(p_y_est, 2, weighted.mean, w = weights)
    p_y_ctl_est_average <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
    
    # correct for any probabilities of 1  
    if (any(p_y_ctl_leq_average == 1, na.rm = T)) {
      p_y_ctl_leq_average[which(p_y_ctl_leq_average == 1)] <- 1 - 1e-7 
    }
    
    if (any(p_y_trt_leq_average == 1, na.rm = T)) {
      p_y_trt_leq_average[which(p_y_trt_leq_average == 1)] <- 1 - 1e-7 
    }
    
    RD_leq <- p_y_trt_leq_average - p_y_ctl_leq_average
    RD_geq <- p_y_ctl_geq_average - p_y_trt_geq_average
    
    
    OR <- (p_y_trt_leq_average/ (1- p_y_trt_leq_average)) / (p_y_ctl_leq_average / (1- p_y_ctl_leq_average))
    
    RR_leq <-  p_y_trt_leq_average / p_y_ctl_leq_average
    RR_geq <- p_y_ctl_geq_average / p_y_trt_geq_average
    

    # set up how to modify utility value
    # base_utility defines the base utility values that we will modify
    # util_modify defines which utility value we want to modify 
    # need to determine the correct ratios for the other values 
    ratio <- NA 
    for (i in 2:(c-1)) {
      if (i < util_modify) {
        ratio[i] <- (base_utility[i] -  base_utility[util_modify])/ (100 -  base_utility[util_modify])
      } else if (i > util_modify) {
        ratio[i] <- (base_utility[i])/(base_utility[util_modify])
      }
    }
    # num_util_above <- c - max(util_modify)
    # num_util_below <- min(util_modify) - 1
    # even_util_no_jump <- rev(seq(0, 100, by = 100/(c-2)))
    # even_util_value <- even_util_no_jump[min(util_modify) ]
    utility_matrix <- matrix(data = NA, nrow = 101, ncol = c)
    utility_matrix[,1] <- 100
    utility_matrix[,c] <- 0
    utility_matrix[,util_modify] <- 0:100
    # pull NA columns 
    for (i in 1:nrow(utility_matrix)) {
      # make catch for if the utility being modified is 2 or c-1
      if (util_modify == 2) {
        utility_matrix[i,(util_modify+1):(c-1)] <- utility_matrix[i,util_modify]*ratio[(util_modify+1):(c-1)]
      } else if (util_modify == c-1) {
        utility_matrix[i,2:(util_modify-1)] <- (100 - utility_matrix[i,util_modify])*ratio[2:(util_modify-1)] + utility_matrix[i,util_modify]
      } else {
        utility_matrix[i,2:(util_modify-1)] <- (100 - utility_matrix[i,util_modify])*ratio[2:(util_modify-1)] + utility_matrix[i,util_modify]
        utility_matrix[i,(util_modify+1):(c-1)] <- utility_matrix[i,util_modify]*ratio[(util_modify+1):(c-1)]
      }
    }
    
    
    j <- 1:(c-1)
    k <- 2:c
    # weighted_RD_B95CI <- matrix(data = NA, nrow = 99, ncol = 2)
    # weighted_log_OR_B95CI <- matrix(data = NA, nrow = 99, ncol = 2)
    # weighted_log_RR_B95CI <- matrix(data = NA, nrow = 99, ncol = 2)
    utility_value <- NA
    for (i in 1:nrow(utility_matrix)) {
      utility_value[i] <- utility_matrix[i, util_modify]
      # bayesian approach 
      numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]))  * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j])) 
      denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) )
      wRD_both[i,s] <- numerator/denominator 
      
      numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j])) 
      denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
      wRD_util[i,s] <- numerator/denominator
      
      # bayesian approach 
      #calculate log weighted OR with control probability as weights
      numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]))  * log(OR[j]))
      denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) )
      log_wOR_both[i,s] <- numerator/denominator
      
      numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(OR[j]))
      denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) )
      log_wOR_util[i,s] <- numerator/denominator
      
      # bayesian approach
      #calculate log weighted RR with control probability as weights
      numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]))  * log(RR_leq[j]))
      denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) )
      log_wRR_both[i,s] <- numerator/denominator
      
      numerator <- sum( (abs(utility_matrix[i,j] - utility_matrix[i,k]))  * log(RR_leq[j]))
      denominator <- sum( (abs(utility_matrix[i,j] - utility_matrix[i,k])) )
      log_wRR_util[i,s] <- numerator/denominator
    }
    
  }
  
  wRD_both_95CI <- t(apply(wRD_both, 1, quantile, probs = c(0.025, 0.975)))
  log_wOR_both_95CI <- t(apply(log_wOR_both, 1, quantile, probs = c(0.025, 0.975)))
  log_wRR_both_95CI <- t(apply(log_wRR_both, 1, quantile, probs = c(0.025, 0.975)))
  
  wRD_util_95CI <- t(apply(wRD_util, 1, quantile, probs = c(0.025, 0.975)))
  log_wOR_util_95CI <- t(apply(log_wOR_util, 1, quantile, probs = c(0.025, 0.975)))
  log_wRR_util_95CI <- t(apply(log_wRR_util, 1, quantile, probs = c(0.025, 0.975)))
  
  
  return(list(utility_value = utility_value,
              wRD_both_95CI = wRD_both_95CI, 
              log_wOR_both_95CI = log_wOR_both_95CI, 
              log_wRR_both_95CI = log_wRR_both_95CI,
              wRD_util_95CI = wRD_util_95CI, 
              log_wOR_util_95CI = log_wOR_util_95CI, 
              log_wRR_util_95CI = log_wRR_util_95CI))
  
}



# adjusted sensitivity analysis drop one level 
sensitivity_utility_droplevel <- function(stanfit, dat, structured_dat, base_utility,
                                            outcome, trt, covs, util_modify, seed = 12345) { 
  set.seed(seed)
  modfit <- as.data.frame(stanfit)
  
  alphas <- modfit[,grep('alpha\\[', colnames(modfit))]
  alpha <- colMeans(alphas)
  
  betas <- modfit[,grep('beta\\[', colnames(modfit))]
  beta <- colMeans(betas)
  beta <- matrix(beta, nrow=1) %*% t(structured_dat$wqrX$Rinv[2:4, 2:4])
  
  c <- length(alpha)/2 +1
  
  predicted_trt_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_ctl_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_trt_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  predicted_ctl_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
  p_y_ctl <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_trt <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_ctl_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  p_y_trt_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
  
  
  
  num_covs <- length(covs)
  covariate_mat <- as.data.frame(matrix(data = NA, nrow = nrow(dat), ncol = num_covs - 1))
  
  # assume the first covariate is the treatment arm 
  for(i in 1:num_covs) {
    if (is.numeric(dat[[covs[i]]]) == T) {
      covariate_mat[,i] <- beta[i] * dat[[covs[i]]]
    } else {
      # only works for numeric and binary with "Yes" as the value
      covariate_mat[,i] <- beta[i] * (dat[[covs[i]]] == "Yes")
    }
  }
  
  for (i in 2:c) {
    predicted_trt_geq[,i-1] <- plogis(alpha[2*i - 2] + rowSums(covariate_mat))
    predicted_ctl_geq[,i-1] <- plogis(alpha[2*i - 3] + rowSums(covariate_mat))
  }
  
  
  predicted_trt_leq <-  1 - predicted_trt_geq
  predicted_ctl_leq <-  1 - predicted_ctl_geq
  
  # calculate p(Y = i | control) for i = 1, ... , c
  for (i in 1:c) {
    if (i == 1) {
      p_y_ctl_est[,1] <-  predicted_ctl_leq[,1]
      p_y_trt_est[,1] <-  predicted_trt_leq[,1]
    } else if (i == 2) {
      p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - p_y_ctl_est[,1]
      p_y_trt_est[,i] <-  predicted_trt_leq[,i] - p_y_trt_est[,1]
    } else if (i == c) {
      p_y_ctl_est[,c] <- 1 - rowSums(p_y_ctl_est[,1:(c-1)])
      p_y_trt_est[,c] <- 1 - rowSums(p_y_trt_est[,1:(c-1)])
    } else {
      p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - rowSums(p_y_ctl_est[,1:(i-1)])
      p_y_trt_est[,i] <-  predicted_trt_leq[,i] - rowSums(p_y_trt_est[,1:(i-1)])
    }
  }
  
  # correct for any negative probabilities 
  if (any(p_y_ctl_est < 0)) {
    p_y_ctl_est[which(p_y_ctl_est < 0)] <- 0 
    p_y_ctl_est <- p_y_ctl_est/rowSums(p_y_ctl_est)
  }
  
  if (any(p_y_trt_est < 0)) {
    p_y_trt_est[which(p_y_trt_est < 0)] <- 0 
    p_y_trt_est <- p_y_trt_est/rowSums(p_y_trt_est)
  }
  
  
  p_y_est <- (p_y_ctl_est + p_y_trt_est)/2
  
  # get weights from the data 
  p_y_ctl <- unname(table(dat[[trt]], dat[[outcome]])[1,])/sum(dat[[trt]] == -0.5)
  p_y_trt <- unname(table(dat[[trt]], dat[[outcome]])[2,])/sum(dat[[trt]] == 0.5)
  p_y <- unname(table(dat[[outcome]]))/nrow(dat)
  
  # use Bayesian bootstrap to marginalize the probabilities
  weights <- t(rdirichlet(1, rep(1, nrow(dat))))
  p_y_ctl_est_bb <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
  p_y_trt_est_bb <- apply(p_y_trt_est, 2, weighted.mean, w = weights)
  p_y_est_bb <- (p_y_ctl_est_bb + p_y_trt_est_bb) /2
  
  p_y_ctl_leq_average <- apply(predicted_ctl_leq, 2, weighted.mean, w = weights)
  p_y_trt_leq_average <- apply(predicted_trt_leq, 2, weighted.mean, w = weights)
  p_y_ctl_geq_average <- apply(predicted_ctl_geq, 2, weighted.mean, w = weights)
  p_y_trt_geq_average <- apply(predicted_trt_geq, 2, weighted.mean, w = weights)
  
  
  RD_leq <- p_y_trt_leq_average - p_y_ctl_leq_average
  RD_geq <- p_y_ctl_geq_average - p_y_trt_geq_average
  
  
  OR <- (p_y_trt_leq_average / (1- p_y_trt_leq_average)) / (p_y_ctl_leq_average / (1- p_y_ctl_leq_average))
  
  RR_leq <- p_y_trt_leq_average / p_y_ctl_leq_average
  RR_geq <- p_y_ctl_geq_average / p_y_trt_geq_average
  
  # set up how to modify utility value
  # base_utility defines the base utility values that we will modify
  # util_modify defines which utility value we want to modify 
  # vary_util_length <- base_utility[util_modify - 1] - base_utility[util_modify + 1]
  vary_util_length <- length(c(base_utility[util_modify - 1]:base_utility[util_modify + 1], base_utility[util_modify + 1]))
  # num_util_above <- c - max(util_modify)
  # num_util_below <- min(util_modify) - 1
  # even_util_no_jump <- rev(seq(0, 100, by = 100/(c-2)))
  # even_util_value <- even_util_no_jump[min(util_modify) ]
  utility_value <- NA
  utility_matrix <- matrix(data = NA, nrow = vary_util_length, ncol = c)
  for (i in 1:c) {
    if (i != util_modify) {
      utility_matrix[,i] <- base_utility[i]
    } else if (i == util_modify) {
      utility_matrix[,i] <- c(base_utility[util_modify - 1]:base_utility[util_modify + 1], base_utility[util_modify + 1])
    }
  }
  
  
  j <- 1:(c-1)
  k <- 2:c
  
  weighted_RD_both <- NA
  weighted_RD_util <- NA
  log_weighted_OR_both <- NA
  log_weighted_OR_util <- NA
  log_weighted_RR_both <- NA
  log_weighted_RR_util <- NA
  # utility_value <- NA
  for (i in 1:nrow(utility_matrix)) {
    utility_value[i] <- utility_matrix[i, util_modify]
    
    # fully bayesian approach 
    # control weighted  
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    weighted_RD_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    weighted_RD_util[i] <- numerator/denominator
    
    
    # bayesian approach
    #calculate weighted OR with control probability as weights
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * log(OR[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    log_weighted_OR_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(OR[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    log_weighted_OR_util[i] <- numerator/denominator
    
    # bayesian approach
    #calculate weighted RR with control probability as weights
    numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) * log(RR_leq[j]))
    denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])))
    log_weighted_RR_both[i] <- numerator/denominator
    
    numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(RR_leq[j]))
    denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
    log_weighted_RR_util[i] <- numerator/denominator
  }
  
  return(list(utility_value = utility_value,
              weighted_RD_both = weighted_RD_both, 
              weighted_RD_util = weighted_RD_util, 
              log_weighted_OR_both = log_weighted_OR_both,
              log_weighted_OR_util = log_weighted_OR_util,
              log_weighted_RR_both = log_weighted_RR_both,
              log_weighted_RR_util = log_weighted_RR_util))
  
}


# sensitivity analysis of changing utility values, CI calculation
sensitivity_utility_CI_droplevel <- function(stanfit, structured_dat, n_post_draws = 4000, dat,  
                                               outcome, trt, covs, base_utility, util_modify, seed = 12345) { 
  set.seed(seed)
  # first calculate P(y >= i | ctl) and P(y >= i | trt) for all i
  stanmod <- as.data.frame(stanfit)
  alphas_post <- stanmod[,grep('alpha\\[', colnames(stanmod))]
  c <- ncol(alphas_post)/2 +1
  
  betas <- stanmod[,grep('beta\\[', colnames(stanmod))]
  betas_post <- as.matrix(betas) %*% t(structured_dat$wqrX$Rinv[2:4, 2:4])
  
  
  PPO_ctl_geq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  PPO_trt_geq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  PPO_ctl_leq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  PPO_trt_leq_averages <- matrix(data = NA, nrow = n_post_draws, ncol = c) 
  
  vary_util_length <- length(c(base_utility[util_modify - 1]:base_utility[util_modify + 1], base_utility[util_modify + 1]))
  
  wRD_both <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  wRD_util <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  log_wOR_both <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  log_wOR_util <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  log_wRR_both <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  log_wRR_ge_both <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  log_wRR_util <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  log_wRR_ge_util <- matrix(data = NA, ncol = n_post_draws, nrow = vary_util_length)
  
  # weights_split <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  # weights_cum <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  # weights_both <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  
  #NB <- matrix(data = NA, nrow = n_post_draws, ncol = 1)
  RD_leq_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  OR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  RR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  RR_save_geq <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  log_OR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  log_RR_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  log_RR_ge_save <- matrix(data = NA, nrow = n_post_draws, ncol = c-1)
  
  foreach (s = 1:n_post_draws) %do% {
    
    predicted_trt_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    predicted_ctl_geq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    predicted_trt_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    predicted_ctl_leq <- matrix(data = NA, nrow = nrow(dat), ncol = c-1) 
    
    # if (iprior == 0){
    #   coefs <- posterior_draws[i, ]
    # } else {
    #   coefs <- c(-coef(b)[1:3], coef(b)[4:9])
    # }
    
    alpha <- alphas_post[s, ]
    beta <- betas_post[s, ]
    
    num_covs <- length(covs)
    covariate_mat <- as.data.frame(matrix(data = NA, nrow = nrow(dat), ncol = num_covs - 1))
    
    # assume the first covariate is the treatment arm 
    for(i in 1:num_covs) {
      if (is.numeric(dat[[covs[i]]]) == T) {
        covariate_mat[,i] <- beta[i] * dat[[covs[i]]]
      } else {
        # only works for numeric and binary with "Yes" as the value
        covariate_mat[,i] <- beta[i] * (dat[[covs[i]]] == "Yes")
      }
    }
    
    for (i in 2:c) {
      predicted_trt_geq[,i-1] <- plogis(as.numeric(alpha[2*i - 2]) + rowSums(covariate_mat))
      predicted_ctl_geq[,i-1] <- plogis(as.numeric(alpha[2*i - 3]) + rowSums(covariate_mat))
    }
    
    predicted_trt_leq <-  1 - predicted_trt_geq
    predicted_ctl_leq <-  1 - predicted_ctl_geq
    
    p_y_trt_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
    p_y_ctl_est <- matrix(data = NA, nrow = nrow(dat), ncol = c) 
    for (i in 1:c) {
      if (i == 1) {
        p_y_ctl_est[,1] <-  predicted_ctl_leq[,1]
        p_y_trt_est[,1] <-  predicted_trt_leq[,1]
      } else if (i == 2){
        p_y_ctl_est[,2] <- predicted_ctl_leq[,i] - predicted_ctl_leq[,1]
        p_y_trt_est[,2] <- predicted_trt_leq[,i] - predicted_trt_leq[,1]
      } else if (i == c) {
        p_y_ctl_est[,c] <- 1 - rowSums(p_y_ctl_est[,1:(c-1)])
        p_y_trt_est[,c] <- 1 - rowSums(p_y_trt_est[,1:(c-1)])
      } else {
        p_y_ctl_est[,i] <-  predicted_ctl_leq[,i] - apply(p_y_ctl_est[,1:(i-1)], 1, sum)
        p_y_trt_est[,i] <-  predicted_trt_leq[,i] - apply(p_y_trt_est[,1:(i-1)], 1, sum)
      }
    }
    
    # correct for any negative probabilities 
    if (any(p_y_ctl_est < 0)) {
      p_y_ctl_est[which(p_y_ctl_est < 0)] <- 0 
      p_y_ctl_est <- p_y_ctl_est/rowSums(p_y_ctl_est)
    }
    
    if (any(p_y_trt_est < 0)) {
      p_y_trt_est[which(p_y_trt_est < 0)] <- 0 
      p_y_trt_est <- p_y_trt_est/rowSums(p_y_trt_est)
    }
    
    
    p_y_est <- (p_y_ctl_est + p_y_trt_est)/2
    
    # get weights from the data 
    p_y_ctl <- unname(table(dat[[trt]], dat[[outcome]])[1,])/sum(dat[[trt]] == -0.5)
    p_y_trt <- unname(table(dat[[trt]], dat[[outcome]])[2,])/sum(dat[[trt]] == 0.5)
    p_y <- as.vector(unname(table(dat[[outcome]]))/nrow(dat))
    
    weights <- t(rdirichlet(1, rep(1, nrow(dat))))
    p_y_ctl_est_bb <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
    p_y_trt_est_bb <- apply(p_y_trt_est, 2, weighted.mean, w = weights)
    p_y_est_bb <- (p_y_ctl_est_bb + p_y_trt_est_bb) /2
    
    p_y_ctl_leq_average <- apply(predicted_ctl_leq, 2, weighted.mean, w = weights)
    p_y_trt_leq_average <- apply(predicted_trt_leq, 2, weighted.mean, w = weights)
    p_y_ctl_geq_average <- apply(predicted_ctl_geq, 2, weighted.mean, w = weights)
    p_y_trt_geq_average <- apply(predicted_trt_geq, 2, weighted.mean, w = weights)
    
    p_y_est_average <- apply(p_y_est, 2, weighted.mean, w = weights)
    p_y_ctl_est_average <- apply(p_y_ctl_est, 2, weighted.mean, w = weights)
    
    # correct for any probabilities of 1  
    if (any(p_y_ctl_leq_average == 1, na.rm = T)) {
      p_y_ctl_leq_average[which(p_y_ctl_leq_average == 1)] <- 1 - 1e-7 
    }
    
    if (any(p_y_trt_leq_average == 1, na.rm = T)) {
      p_y_trt_leq_average[which(p_y_trt_leq_average == 1)] <- 1 - 1e-7 
    }
    
    RD_leq <- p_y_trt_leq_average - p_y_ctl_leq_average
    RD_geq <- p_y_ctl_geq_average - p_y_trt_geq_average
    
    
    OR <- (p_y_trt_leq_average/ (1- p_y_trt_leq_average)) / (p_y_ctl_leq_average / (1- p_y_ctl_leq_average))
    
    RR_leq <-  p_y_trt_leq_average / p_y_ctl_leq_average
    RR_geq <- p_y_ctl_geq_average / p_y_trt_geq_average
    
    
    # set up how to modify utility value
    # base_utility defines the base utility values that we will modify
    # util_modify defines which utility value we want to modify 
    # need to determine the correct ratios for the other values 
    # vary_util_length <- base_utility[util_modify - 1] - base_utility[util_modify + 1]
    vary_util_length <- length(c(base_utility[util_modify - 1]:base_utility[util_modify + 1], base_utility[util_modify + 1]))
    # num_util_above <- c - max(util_modify)
    # num_util_below <- min(util_modify) - 1
    # even_util_no_jump <- rev(seq(0, 100, by = 100/(c-2)))
    # even_util_value <- even_util_no_jump[min(util_modify) ]
    utility_matrix <- matrix(data = NA, nrow = vary_util_length, ncol = c)
    for (i in 1:c) {
      if (i != util_modify) {
        utility_matrix[,i] <- base_utility[i]
      } else if (i == util_modify) {
        utility_matrix[,i] <- c(base_utility[util_modify - 1]:base_utility[util_modify + 1], base_utility[util_modify + 1])
      }
    }
    
    
    j <- 1:(c-1)
    k <- 2:c
    # weighted_RD_B95CI <- matrix(data = NA, nrow = 99, ncol = 2)
    # weighted_log_OR_B95CI <- matrix(data = NA, nrow = 99, ncol = 2)
    # weighted_log_RR_B95CI <- matrix(data = NA, nrow = 99, ncol = 2)
    utility_value <- NA
    for (i in 1:nrow(utility_matrix)) {
      utility_value[i] <- utility_matrix[i, util_modify]
      # bayesian approach 
      numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]))  * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j])) 
      denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) )
      wRD_both[i,s] <- numerator/denominator 
      
      numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_trt_leq_average[j] - p_y_ctl_leq_average[j])) 
      denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])))
      wRD_util[i,s] <- numerator/denominator
      
      # bayesian approach 
      #calculate log weighted OR with control probability as weights
      numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]))  * log(OR[j]))
      denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) )
      log_wOR_both[i,s] <- numerator/denominator
      
      numerator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) * log(OR[j]))
      denominator <- sum((abs(utility_matrix[i,j] - utility_matrix[i,k])) )
      log_wOR_util[i,s] <- numerator/denominator
      
      # bayesian approach
      #calculate log weighted RR with control probability as weights
      numerator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j]))  * log(RR_leq[j]))
      denominator <- sum((p_y_ctl_est_bb[j] + p_y_ctl_est_bb[k]) * (abs(utility_matrix[i,j] - utility_matrix[i,k])) * (p_y_ctl_leq_average[j] * (1 - p_y_ctl_leq_average[j])) )
      log_wRR_both[i,s] <- numerator/denominator
      
      numerator <- sum( (abs(utility_matrix[i,j] - utility_matrix[i,k]))  * log(RR_leq[j]))
      denominator <- sum( (abs(utility_matrix[i,j] - utility_matrix[i,k])) )
      log_wRR_util[i,s] <- numerator/denominator
    }
    
  }
  
  wRD_both_95CI <- t(apply(wRD_both, 1, quantile, probs = c(0.025, 0.975)))
  log_wOR_both_95CI <- t(apply(log_wOR_both, 1, quantile, probs = c(0.025, 0.975)))
  log_wRR_both_95CI <- t(apply(log_wRR_both, 1, quantile, probs = c(0.025, 0.975)))
  
  wRD_util_95CI <- t(apply(wRD_util, 1, quantile, probs = c(0.025, 0.975)))
  log_wOR_util_95CI <- t(apply(log_wOR_util, 1, quantile, probs = c(0.025, 0.975)))
  log_wRR_util_95CI <- t(apply(log_wRR_util, 1, quantile, probs = c(0.025, 0.975)))
  
  
  return(list(utility_value = utility_value,
              wRD_both_95CI = wRD_both_95CI, 
              log_wOR_both_95CI = log_wOR_both_95CI, 
              log_wRR_both_95CI = log_wRR_both_95CI,
              wRD_util_95CI = wRD_util_95CI, 
              log_wOR_util_95CI = log_wOR_util_95CI, 
              log_wRR_util_95CI = log_wRR_util_95CI))
  
}
